"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["10120"],{41558(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.banca.fase_com_banca_da_segunda_instancia_sem_recurso_para_julgar","status":422,"titulo":"A fase prev\xea banca que julga o recurso em 2\xaa inst\xe2ncia, e n\xe3o h\xe1 recurso para ela julgar"},"descricao":{"codigo":"uniplus.selecao.banca.fase_com_banca_da_segunda_instancia_sem_recurso_para_julgar","requisitos":["UNI-REQ-0454","UNI-REQ-0491"],"oQueAconteceu":["A fase prev\xea uma banca com o papel de julgar o recurso em 2\xaa inst\xe2ncia, e n\xe3o h\xe1 recurso que ela possa julgar (UNI-REQ-0491). A banca de 2\xaa inst\xe2ncia da fase julga o recurso da pr\xf3pria fase e os recursos das etapas dela que n\xe3o t\xeam banca de 2\xaa inst\xe2ncia pr\xf3pria. Por isso a banca da fase \xe9 aceita quando o recurso da fase admite inst\xe2ncia superior, ou quando uma etapa da fase tem recurso que admite inst\xe2ncia superior e n\xe3o tem banca de 2\xaa inst\xe2ncia pr\xf3pria. Se todas as etapas com esse recurso j\xe1 t\xeam a sua banca, a da fase sobra e \xe9 recusada.","O rascunho do processo aceita essa banca, porque \xe9 montado aos poucos. A recusa sai na publica\xe7\xe3o e na retifica\xe7\xe3o em ato \xfanico, uma por banca, como o c\xf3digo desta p\xe1gina no corpo da resposta, e n\xe3o na lista `errors[]`. O campo \xe9 `fases[i].bancasRequeridas[p]`, em que `i` \xe9 a posi\xe7\xe3o da fase e `p`, a da banca, e a resposta traz o c\xf3digo da fase e a identifica\xe7\xe3o da banca em `identificadores`. Nesse lugar, a recusa de [mais de uma banca de 2\xaa inst\xe2ncia](/erros/uniplus.selecao.banca.fase_com_mais_de_uma_banca_da_segunda_instancia) n\xe3o sai.","A mensagem da resposta cita a fase pelo c\xf3digo e a banca pelo nome do tipo e pela posi\xe7\xe3o dela, e tem duas formas:","- nenhum recurso admite inst\xe2ncia superior: \\"A fase \'*c\xf3digo da fase*\' prev\xea a banca \'*tipo e posi\xe7\xe3o*\', com o papel \'Julga o recurso em 2\xaa inst\xe2ncia\', e nenhum recurso da fase ou das etapas dela admite inst\xe2ncia superior. A banca de 2\xaa inst\xe2ncia da fase julga o recurso da fase e os das etapas dela que n\xe3o t\xeam banca de 2\xaa inst\xe2ncia pr\xf3pria. Retire essa banca, ou declare que o recurso da fase, ou o de uma etapa dela sem banca de 2\xaa inst\xe2ncia pr\xf3pria, admite inst\xe2ncia superior.\\";\\n- s\xf3 admitem etapas que j\xe1 t\xeam a sua banca: \\"A fase \'*c\xf3digo da fase*\' prev\xea a banca \'*tipo e posi\xe7\xe3o*\', com o papel \'Julga o recurso em 2\xaa inst\xe2ncia\', e n\xe3o h\xe1 recurso para ela julgar: o recurso da fase n\xe3o admite inst\xe2ncia superior, e cada etapa da fase com recurso que admite inst\xe2ncia superior j\xe1 tem a sua banca de 2\xaa inst\xe2ncia, que o julga. A banca de 2\xaa inst\xe2ncia da fase julga o recurso da fase e os das etapas dela que n\xe3o t\xeam banca de 2\xaa inst\xe2ncia pr\xf3pria. Retire essa banca; ou retire a banca de 2\xaa inst\xe2ncia de uma dessas etapas, para que a da fase julgue o recurso dela; ou declare que o recurso da fase, ou o de uma etapa dela sem banca de 2\xaa inst\xe2ncia pr\xf3pria, admite inst\xe2ncia superior.\\""],"comoResolver":["Escolha um dos caminhos:","- retire a banca de 2\xaa inst\xe2ncia da fase;\\n- ou retire a banca de 2\xaa inst\xe2ncia de uma etapa da fase com recurso que admite inst\xe2ncia superior, para que a banca da fase julgue o recurso dela;\\n- ou declare que o recurso da fase, ou o de uma etapa dela sem banca de 2\xaa inst\xe2ncia pr\xf3pria, admite inst\xe2ncia superior.","O painel de conformidade aponta a pend\xeancia antes da publica\xe7\xe3o, no item `cronograma_banca_da_segunda_instancia_com_recurso_para_julgar`."],"ondeAparece":["- Publica\xe7\xe3o inicial do processo seletivo\\n- Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Banca"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);